    basic: [[5, '「자전거가 주는 도움」에서 「이것만이 아니다」라고 했어요. 「이것」이 가리키는 내용을 골라요.', '🚲'], [7, '문장에서 가리키는 말을 찾고 바로 앞에서 그 내용을 찾아요. 가리키는 말과 가리키는 내용을 이어요.', '🔗'], [9, '같은 말을 되풀이하지 않고 「그것」이라고 쓰면 무엇이 좋을까요? 좋은 점을 **모두** 골라요.', '✨']],
    lev: { 기본: { q: '짝의 책상 위 지우개, 내 손의 연필, 창가의 화분을 각각 가리킬 때 쓰는 말을 말해 봐요.', a: '지우개 — 그것 · 연필 — 이것 · 화분 — 저것', steps: ['말하는 사람에게 가까운지 본다', '듣는 사람에게 가까운지 본다', '둘 다에게서 멀면 「저것」이라고 한다'] }, 도전: { q: '「민서는 필통에 노란 색연필을 늘 넣고 다닌다. 짝이 색을 찾지 못하자 민서는 노란 색연필 그것을 떠올렸다」에서 「그것」이 가리키는 것을 말하고, 가리키는 말을 써서 글이 어떻게 달라졌는지 말해 봐요.', a: '그것 = 노란 색연필 · 같은 말을 되풀이하지 않아 문장이 간결해지고 흐름이 매끄러워진다', steps: ['「그것」 바로 앞을 읽어 가리키는 내용을 찾는다', '되풀이해서 쓴 문장과 견준다', '달라진 점을 말한다'] }, 심화: { q: '오늘 있었던 일을 두 문장으로 쓰되, 둘째 문장에 「그것」이나 「이것」을 넣어 앞 문장의 내용을 가리키게 써 봐요.', a: '여러 답 (예: 점심에 떡볶이가 나왔다. 그것은 참 매웠다.)', open: true } },
